+using System;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using Xunit;
+
+namespace ContosoUniversity.Tests
+{
+    public class NotificationServiceTests : IDisposable
+    {
+        private readonly NotificationService _service;
+
+        public NotificationServiceTests()
+        {
+            _service = new NotificationService();
+            // Drain any leftover notifications from other tests (static queue)
+            while (_service.ReceiveNotification() != null) { }
+        }
+
+        public void Dispose()
+        {
+            _service.Dispose();
+        }
+
+        [Fact]
+        public void SendNotification_WithDisplayName_EnqueuesNotification()
+        {
+            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");
+
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("1", notification.EntityId);
+            Assert.Equal("CREATE", notification.Operation);
+            Assert.Contains("Student 'John Doe'", notification.Message);
+            Assert.Contains("created", notification.Message);
+            Assert.Equal("Admin", notification.CreatedBy);
+            Assert.False(notification.IsRead);
+            Assert.True(notification.CreatedAt <= DateTime.Now);
+            Assert.True(notification.CreatedAt > DateTime.Now.AddSeconds(-5));
+        }
+
+        [Fact]
+        public void SendNotification_WithoutDisplayName_UsesEntityId()
+        {
+            _service.SendNotification("Course", "42", EntityOperation.UPDATE, "System");
+
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Course", notification.EntityType);
+            Assert.Equal("42", notification.EntityId);
+            Assert.Equal("UPDATE", notification.Operation);
+            Assert.Contains("(ID: 42)", notification.Message);
+            Assert.Contains("updated", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
+        {
+            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");
+
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("DELETE", notification.Operation);
+            Assert.Contains("deleted", notification.Message);
+            Assert.Contains("Department 'Engineering'", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_NullUserName_DefaultsToSystem()
+        {
+            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
+
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void SendNotification_WithExplicitNullUserName_DefaultsToSystem()
+        {
+            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);
+
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void ReceiveNotification_EmptyQueue_ReturnsNull()
+        {
+            var notification = _service.ReceiveNotification();
+            Assert.Null(notification);
+        }
+
+        [Fact]
+        public void ReceiveNotification_DequeuesInFifoOrder()
+        {
+            _service.SendNotification("Student", "1", "First", EntityOperation.CREATE, "User1");
+            _service.SendNotification("Course", "2", "Second", EntityOperation.UPDATE, "User2");
+
+            var first = _service.ReceiveNotification();
+            var second = _service.ReceiveNotification();
+            var third = _service.ReceiveNotification();
+
+            Assert.NotNull(first);
+            Assert.Equal("Student", first.EntityType);
+            Assert.Equal("1", first.EntityId);
+
+            Assert.NotNull(second);
+            Assert.Equal("Course", second.EntityType);
+            Assert.Equal("2", second.EntityId);
+
+            Assert.Null(third);
+        }
+
+        [Fact]
+        public void MarkAsRead_DoesNotThrow()
+        {
+            // MarkAsRead is a no-op for in-memory implementation
+            var exception = Record.Exception(() => _service.MarkAsRead(1));
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendNotification_TwoArgOverload_EnqueuesCorrectly()
+        {
+            _service.SendNotification("Instructor", "7", EntityOperation.DELETE);
+
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Instructor", notification.EntityType);
+            Assert.Equal("7", notification.EntityId);
+            Assert.Equal("DELETE", notification.Operation);
+            Assert.Contains("(ID: 7)", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_CreateMessage_ContainsNewPrefix()
+        {
+            _service.SendNotification("Student", "1", "Test User", EntityOperation.CREATE, "Admin");
+
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.StartsWith("New", notification.Message);
+        }
+
+        [Fact]
+        public void Dispose_DoesNotThrow()
+        {
+            var service = new NotificationService();
+            var exception = Record.Exception(() => service.Dispose());
+            Assert.Null(exception);
+        }
+    }
+}
