using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanBeCreatedWithInMemoryProvider()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            Assert.NotNull(context);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.Notifications);
            Assert.NotNull(context.People);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };
            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.First();
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
            Assert.Equal(DateTime.Parse("2023-01-01"), retrieved.EnrollmentDate);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveCourse()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var dept = new Department { Name = "TestDept", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 101, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.First();
            Assert.Equal(101, retrieved.CourseID);
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(3, retrieved.Credits);
            Assert.Equal(dept.DepartmentID, retrieved.DepartmentID);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveDepartment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 500000,
                StartDate = DateTime.Parse("2020-01-01")
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var retrieved = context.Departments.First();
            Assert.Equal("Engineering", retrieved.Name);
            Assert.Equal(500000, retrieved.Budget);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveInstructor()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = DateTime.Parse("2015-06-01")
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var retrieved = context.Instructors.First();
            Assert.Equal("Jane", retrieved.FirstMidName);
            Assert.Equal("Doe", retrieved.LastName);
            Assert.Equal(DateTime.Parse("2015-06-01"), retrieved.HireDate);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_CompositeKey()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 100, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var assignment = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            var retrieved = context.CourseAssignments.First();
            Assert.Equal(course.CourseID, retrieved.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void SchoolContext_CanAddEnrollment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
            context.Students.Add(student);
            context.SaveChanges();

            var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 200, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();

            var retrieved = context.Enrollments.First();
            Assert.Equal(student.ID, retrieved.StudentID);
            Assert.Equal(course.CourseID, retrieved.CourseID);
            Assert.Equal(Grade.A, retrieved.Grade);
        }

        [Fact]
        public void SchoolContext_CanAddOfficeAssignment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 101" };
            context.OfficeAssignments.Add(office);
            context.SaveChanges();

            var retrieved = context.OfficeAssignments.First();
            Assert.Equal(instructor.ID, retrieved.InstructorID);
            Assert.Equal("Room 101", retrieved.Location);
        }

        [Fact]
        public void SchoolContext_CanAddNotification()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now,
                CreatedBy = "Test",
                IsRead = false
            };
            context.Notifications.Add(notification);
            context.SaveChanges();

            var retrieved = context.Notifications.First();
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("1", retrieved.EntityId);
            Assert.Equal("CREATE", retrieved.Operation);
            Assert.Equal("Test message", retrieved.Message);
            Assert.Equal("Test", retrieved.CreatedBy);
            Assert.False(retrieved.IsRead);
        }
    }
}

using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsStudents()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Contains(context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
            Assert.Contains(context.Students, s => s.LastName == "Alonso" && s.FirstMidName == "Meredith");
            Assert.Contains(context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
        }

        [Fact]
        public void Initialize_SeedsInstructors()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
            Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
            Assert.Contains(context.Instructors, i => i.LastName == "Fakhouri");
            Assert.Contains(context.Instructors, i => i.LastName == "Harui");
            Assert.Contains(context.Instructors, i => i.LastName == "Kapoor");
            Assert.Contains(context.Instructors, i => i.LastName == "Zheng");
        }

        [Fact]
        public void Initialize_SeedsDepartments()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
            Assert.Contains(context.Departments, d => d.Name == "English" && d.Budget == 350000);
            Assert.Contains(context.Departments, d => d.Name == "Mathematics" && d.Budget == 100000);
            Assert.Contains(context.Departments, d => d.Name == "Engineering");
            Assert.Contains(context.Departments, d => d.Name == "Economics");
        }

        [Fact]
        public void Initialize_SeedsCourses()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
            Assert.Contains(context.Courses, c => c.Title == "Chemistry" && c.CourseID == 1050 && c.Credits == 3);
            Assert.Contains(context.Courses, c => c.Title == "Calculus" && c.CourseID == 1045 && c.Credits == 4);
            Assert.Contains(context.Courses, c => c.Title == "Literature" && c.CourseID == 2042);
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
            var fakhouri = context.Instructors.Single(i => i.LastName == "Fakhouri");
            var office = context.OfficeAssignments.Find(fakhouri.ID);
            Assert.NotNull(office);
            Assert.Equal("Smith 17", office.Location);
        }

        [Fact]
        public void Initialize_SeedsCourseAssignments()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsEnrollments()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
            var alexander = context.Students.Single(s => s.LastName == "Alexander");
            var alexanderEnrollments = context.Enrollments.Where(e => e.StudentID == alexander.ID).ToList();
            Assert.Equal(3, alexanderEnrollments.Count);
        }

        [Fact]
        public void Initialize_DoesNotReseedIfStudentsExist()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            // Seed once
            DbInitializer.Initialize(context);
            var initialStudentCount = context.Students.Count();

            // Seed again — should be a no-op
            DbInitializer.Initialize(context);
            Assert.Equal(initialStudentCount, context.Students.Count());
        }

        [Fact]
        public void Initialize_DepartmentsHaveAdministrators()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            var english = context.Departments.Single(d => d.Name == "English");
            Assert.NotNull(english.InstructorID);
            var admin = context.Instructors.Find(english.InstructorID);
            Assert.NotNull(admin);
            Assert.Equal("Abercrombie", admin.LastName);
        }

        [Fact]
        public void Initialize_EnrollmentsHaveCorrectGrades()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            var alexander = context.Students.Single(s => s.LastName == "Alexander");
            var chemCourse = context.Courses.Single(c => c.Title == "Chemistry");
            var chemEnrollment = context.Enrollments.Single(e =>
                e.StudentID == alexander.ID && e.CourseID == chemCourse.CourseID);
            Assert.Equal(Grade.A, chemEnrollment.Grade);
        }
    }
}

