        [Fact]
        public void Instructor_Properties_SetCorrectly()
        {
            var date = DateTime.Parse("2020-01-15");
            var instructor = new Instructor
            {
                ID = 5,
                FirstMidName = "Jane",
                LastName = "Smith",
                HireDate = date
            };
            Assert.Equal(5, instructor.ID);
            Assert.Equal("Jane", instructor.FirstMidName);
            Assert.Equal("Smith", instructor.LastName);
            Assert.Equal(date, instructor.HireDate);
        }

