            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/uploads/test.jpg", course.TeachingMaterialImagePath);
        }

        // Department model
        [Fact]
        public void Department_Properties_SetCorrectly()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 500000,
                StartDate = DateTime.Parse("2020-01-01"),
                InstructorID = 3
            };
            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(500000, dept.Budget);
            Assert.Equal(3, dept.InstructorID);
        }

        // Enrollment model
        [Fact]
        public void Enrollment_Properties_SetCorrectly()
        {
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 100,
                StudentID = 5,
                Grade = Grade.B
            };
            Assert.Equal(1, enrollment.EnrollmentID);
            Assert.Equal(100, enrollment.CourseID);
            Assert.Equal(5, enrollment.StudentID);
            Assert.Equal(Grade.B, enrollment.Grade);
        }

        [Fact]
        public void Enrollment_Grade_CanBeNull()
        {
            var enrollment = new Enrollment { EnrollmentID = 1, CourseID = 100, StudentID = 5 };
            Assert.Null(enrollment.Grade);
        }

        // Notification model
        [Fact]
        public void Notification_Properties_SetCorrectly()
        {
            var now = DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = true,
                ReadAt = now
            };
            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Test", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.True(notification.IsRead);
            Assert.Equal(now, notification.ReadAt);
        }

        [Fact]
        public void Notification_ReadAt_CanBeNull()
        {
            var notification = new Notification
            {
                EntityType = "X", EntityId = "1", Operation = "CREATE",
                Message = "M", CreatedAt = DateTime.Now
            };
            Assert.Null(notification.ReadAt);
        }

        // OfficeAssignment model
        [Fact]
        public void OfficeAssignment_Properties_SetCorrectly()
        {
            var office = new OfficeAssignment { InstructorID = 3, Location = "Room 101" };
            Assert.Equal(3, office.InstructorID);
            Assert.Equal("Room 101", office.Location);
        }

        // CourseAssignment model
        [Fact]
        public void CourseAssignment_Properties_SetCorrectly()
        {
            var ca = new CourseAssignment { InstructorID = 1, CourseID = 100 };
            Assert.Equal(1, ca.InstructorID);
            Assert.Equal(100, ca.CourseID);
        }

        // Grade enum
        [Fact]
        public void Grade_EnumValues()
        {
            Assert.Equal(0, (int)Grade.A);
            Assert.Equal(1, (int)Grade.B);
            Assert.Equal(2, (int)Grade.C);
            Assert.Equal(3, (int)Grade.D);
            Assert.Equal(4, (int)Grade.F);
        }

        // EntityOperation enum
        [Fact]
        public void EntityOperation_EnumValues()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }

        // View Models
        [Fact]
        public void AssignedCourseData_Properties()
        {
            var acd = new AssignedCourseData { CourseID = 1, Title = "Test", Assigned = true };
            Assert.Equal(1, acd.CourseID);
            Assert.Equal("Test", acd.Title);
            Assert.True(acd.Assigned);
        }

        [Fact]
        public void EnrollmentDateGroup_Properties()
        {
            var edg = new EnrollmentDateGroup
            {
                EnrollmentDate = DateTime.Parse("2023-01-01"),
                StudentCount = 5
            };
            Assert.Equal(DateTime.Parse("2023-01-01"), edg.EnrollmentDate);
            Assert.Equal(5, edg.StudentCount);
        }

        [Fact]
        public void EnrollmentDateGroup_EnrollmentDate_CanBeNull()
        {
            var edg = new EnrollmentDateGroup { StudentCount = 3 };
            Assert.Null(edg.EnrollmentDate);
        }

        [Fact]
        public void InstructorIndexData_Properties()
        {
            var iid = new InstructorIndexData();
            Assert.Null(iid.Instructors);
            Assert.Null(iid.Courses);
            Assert.Null(iid.Enrollments);
        }

        // Department nullable InstructorID
        [Fact]
        public void Department_InstructorID_CanBeNull()
        {
            var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };
            Assert.Null(dept.InstructorID);
        }
    }
}

