using System;
using System.Linq;
using System.Net;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestHelpers.CreateSeededContext();
            _controller = new StudentsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                _controller.ControllerContext.HttpContext,
                Moq.Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        // Index tests
        [Fact]
        public void Index_NoParams_ReturnsViewWithAllStudents()
        {
            var result = _controller.Index(null, null, null, null) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Equal(3, model.Count); // seeded 3 students
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            var result = _controller.Index(null, null, "Alexander", null) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Single(model);
            Assert.Equal("Alexander", model[0].LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersStudents()
        {
            var result = _controller.Index(null, null, "Carson", null) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Single(model);
            Assert.Equal("Carson", model[0].FirstMidName);
        }

        [Fact]
        public void Index_NameDescSort_SortsDescending()
        {
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.True(model.Count > 1);
            // Should be sorted descending by LastName
            Assert.True(string.Compare(model[0].LastName, model[1].LastName) >= 0);
        }

        [Fact]
        public void Index_DateSort_SortsByDateAscending()
        {
            var result = _controller.Index("Date", null, null, null) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.True(model.Count > 1);
            Assert.True(model[0].EnrollmentDate <= model[1].EnrollmentDate);
        }

        [Fact]
        public void Index_DateDescSort_SortsByDateDescending()
        {
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.True(model.Count > 1);
            Assert.True(model[0].EnrollmentDate >= model[1].EnrollmentDate);
        }

        [Fact]
        public void Index_DefaultSort_SortsByLastNameAscending()
        {
            var result = _controller.Index(null, null, null, null) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.True(model.Count > 1);
            Assert.True(string.Compare(model[0].LastName, model[1].LastName) <= 0);
        }

        [Fact]
        public void Index_SearchStringProvided_ResetsPageTo1()
        {
            var result = _controller.Index(null, null, "A", 5) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            var result = _controller.Index(null, "Alexander", null, null) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Single(model);
        }

        [Fact]
        public void Index_SetsViewBagSortParms()
        {
            var result = _controller.Index(null, null, null, null) as ViewResult;
            Assert.NotNull(result);
            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_NameDescSort_ViewBagNameSortParmIsEmpty()
        {
            _controller.Index("name_desc", null, null, null);
            Assert.Equal("", _controller.ViewBag.NameSortParm);
        }

        [Fact]
        public void Index_DateSort_ViewBagDateSortParmIsDateDesc()
        {
            _controller.Index("Date", null, null, null);
            Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
        }

        // Details tests
        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            var student = _context.Students.First();
            var result = _controller.Details(student.ID) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as Student;
            Assert.NotNull(model);
            Assert.Equal(student.ID, model.ID);
            Assert.Equal(student.LastName, model.LastName);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null) as StatusCodeResult;
            Assert.NotNull(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
        }

        // Create GET
        [Fact]
        public void Create_Get_ReturnsViewWithStudentDefaultDate()
        {
            var result = _controller.Create() as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as Student;
            Assert.NotNull(model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        // Create POST
        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-09-01")
            };
            var result = _controller.Create(student) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);

            // Verify student was added
            Assert.Contains(_context.Students, s => s.FirstMidName == "New" && s.LastName == "Student");
        }

        [Fact]
        public void Create_Post_MinDateEnrollment_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "Bad",
                LastName = "Date",
                EnrollmentDate = DateTime.MinValue
            };
            var result = _controller.Create(student) as ViewResult;
            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_TooEarlyDate_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "Bad",
                LastName = "Date",
                EnrollmentDate = new DateTime(1752, 1, 1)
            };
            var result = _controller.Create(student) as ViewResult;
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        // Edit GET
        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = _context.Students.First();
            var result = _controller.Edit(student.ID) as ViewResult;
            Assert.NotNull(result);
            var model = result.Model as Student;
            Assert.NotNull(model);
            Assert.Equal(student.ID, model.ID);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null) as StatusCodeResult;
            Assert.NotNull(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Edit(99999) as NotFoundResult;
            Assert.NotNull(result);
        }

        // Edit POST
        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var student = _context.Students.AsNoTracking().First();
            student.FirstMidName = "Updated";

            // Need a fresh context to avoid tracking conflict
            var freshContext = TestHelpers.CreateInMemoryContext();
            // Copy data from seeded context
            foreach (var s in _context.Students.AsNoTracking().ToList())
                freshContext.Students.Add(s);
            freshContext.SaveChanges();

